<script setup>
import {ref} from 'vue'; import {Head,router} from '@inertiajs/vue3'; import Layout from '@/Layouts/main.vue';
const props=defineProps({members:Object,filters:Object}); const search=ref(props.filters.search||'');
const filter=()=>router.get(route('members.index'),{search:search.value},{preserveState:true,replace:true}); const toggle=m=>router.patch(route('members.status',m.id),{}, {preserveScroll:true});
</script>
<template><Layout><Head title="Socios"/><main class="page"><header><div><small>DIRECTORIO</small><h1>Socios</h1><p>Consulta los socios autorregistrados y administra su acceso.</p></div><div><a :href="route('exports.members')">Exportar socios</a><a :href="route('exports.summary')">Exportar resumen</a></div></header><section class="toolbar"><input v-model="search" @keyup.enter="filter" placeholder="Buscar por nombre, DNI, código o correo"><button @click="filter">Buscar</button><span>{{members.total}} socios</span></section><section class="panel"><table><thead><tr><th>Socio</th><th>Contacto</th><th>Registro</th><th>Disponibles</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="m in members.data" :key="m.id"><td><b>{{m.name}}</b><small>{{m.member_code}}</small></td><td>{{m.email||'Sin correo'}}<small>{{m.phone||'Sin celular'}}</small></td><td>{{new Date(m.created_at).toLocaleDateString('es-PE')}}</td><td>{{m.available_coupons_count}}</td><td><span :class="m.status">{{m.status==='active'?'Activo':'Bloqueado'}}</span></td><td><button @click="toggle(m)">{{m.status==='active'?'Bloquear':'Activar'}}</button></td></tr></tbody></table></section></main></Layout></template>
<style scoped>.page{max-width:1400px;margin:auto;color:#332820}.page>header{display:flex;justify-content:space-between;align-items:end}.page>header>div:last-child{display:flex;gap:8px}.page>header a{background:#576443;color:white;border-radius:8px;padding:10px 13px}.page>header small{color:#993b2a;letter-spacing:.2em;font-weight:800}h1{font:36px Georgia;margin:5px 0}.toolbar,.panel{background:white;padding:15px;margin-top:22px}.toolbar{display:flex;gap:10px;align-items:center;border-radius:14px 14px 0 0}.toolbar input{flex:1;padding:10px;border:1px solid #ddd4c6;border-radius:8px}.toolbar button,td button{background:white;border:1px solid #993b2a;color:#993b2a;border-radius:8px;padding:8px 12px}.panel{margin-top:0;border-radius:0 0 14px 14px;overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:14px;text-align:left;border-top:1px solid #eee8dd}td small{display:block;color:#887e75}.active,.blocked{display:inline-block;padding:6px 10px;border-radius:20px}.active{background:#e4eee1;color:#49603f}.blocked{background:#f4dfd9;color:#993b2a}@media(max-width:700px){.page>header{align-items:start;flex-direction:column;gap:12px}.toolbar{flex-wrap:wrap}}</style>
